      '// Package cache implements a small TTL cache.\npackage cache\n\nimport (\n	"errors"\n	"fmt"\n	"sync"\n	"time"\n)\n\nvar ErrMissing = errors.New("cache: missing key")\n\ntype entry[V any] struct {\n	value   V\n	expires time.Time\n}\n\n// Cache is safe for concurrent use.\ntype Cache[K comparable, V any] struct {\n	mu    sync.RWMutex\n	items map[K]entry[V]\n	ttl   time.Duration\n}\n\nfunc New[K comparable, V any](ttl time.Duration) *Cache[K, V] {\n	return &Cache[K, V]{items: make(map[K]entry[V]), ttl: ttl}\n}\n\nfunc (c *Cache[K, V]) Get(key K) (V, error) {\n	c.mu.RLock()\n	defer c.mu.RUnlock()\n	e, ok := c.items[key]\n	if !ok || time.Now().After(e.expires) {\n		var zero V\n		return zero, fmt.Errorf("get %v: %w", key, ErrMissing)\n	}\n	return e.value, nil\n}\n\nconst raw = `line one\nline two`\n\nfunc main() {\n	c := New[string, int](5 * time.Second)\n	for i := 0; i < 0x10; i++ {\n		go func(n int) { _ = n + \'a\' }(i)\n	}\n	_ = c\n}\n',
