      '{-# LANGUAGE OverloadedStrings #-}\n{-# LANGUAGE ScopedTypeVariables #-}\n-- | A small inventory module.\nmodule Inventory\n  ( Item (..)\n  , restock\n  , total\n  ) where\n\nimport qualified Data.Map.Strict as Map\nimport Data.Maybe (fromMaybe)\n\n{- Block comment {- with a nested one -} still comment -}\n\ndata Item = Item\n  { itemName  :: String\n  , itemCount :: !Int\n  , itemPrice :: Double\n  } deriving (Show, Eq)\n\nnewtype Sku = Sku Int deriving stock (Eq, Ord)\n\ntype Stock = Map.Map Sku Item\n\n-- | Adds n units, creating the item if missing.\nrestock :: Sku -> Int -> Stock -> Stock\nrestock sku n = Map.alter bump sku\n  where\n    bump Nothing = Just (Item "unnamed" n 0.0)\n    bump (Just it) = Just it { itemCount = itemCount it + n }\n\ntotal :: Stock -> Double\ntotal stock = sum [ fromIntegral (itemCount i) * itemPrice i | i <- Map.elems stock ]\n\nclassify :: Int -> String\nclassify n\n  | n < 0 = "negative"\n  | n == 0 = "zero"\n  | otherwise = "positive"\n\narrows :: Int -> Int\narrows x\' = x\' --> 1 -- a real comment\n  where a --> b = a + b\n\nchars :: [Char]\nchars = [\'a\', \'\\n\', \'\\\'\', \'\\x41\']\n\nmain :: IO ()\nmain = do\n  let s = restock (Sku 1) 5 Map.empty\n      hex = 0xFF :: Int\n      big = 1_000_000 :: Integer\n  print (total s, hex, big, 2.5e-3 :: Double)\n  mapM_ (putStrLn . classify) [-1, 0, 1]\n  putStrLn \$ fromMaybe "none" (Just "some \\"quoted\\" text")\n',
