  'java':
      'package com.example.orders;\n\nimport java.util.*;\nimport java.util.function.Function;\nimport static java.util.Objects.requireNonNull;\n\n/**\n * Processes orders.\n * @author Ada\n * @since 21\n */\npublic sealed interface Shape permits Circle, Square {}\n\nrecord Circle(double radius) implements Shape {}\n\nnon-sealed class Square implements Shape {\n    final int side;\n    Square(int side) { this.side = side; }\n}\n\n@FunctionalInterface\ninterface Pricing extends Function<Order, Long> {}\n\npublic final class OrderService {\n    private static final long LIMIT = 10_000L;\n    private static final int MASK = 0x7F_FF;\n    private final Map<String, List<Order>> byCustomer = new HashMap<>();\n\n    @Override\n    public String toString() {\n        return "OrderService{customers=" + byCustomer.size() + "}";\n    }\n\n    @SuppressWarnings("unchecked")\n    public <T extends Order> Optional<T> latest(String customer) {\n        var orders = byCustomer.getOrDefault(requireNonNull(customer), List.of());\n        if (orders.isEmpty()) return Optional.empty();\n        return Optional.of((T) orders.get(orders.size() - 1));\n    }\n\n    static double area(Shape shape) {\n        return switch (shape) {\n            case Circle c when c.radius() > 0 -> Math.PI * c.radius() * c.radius();\n            case Circle c -> 0.0;\n            case Square s -> {\n                double side = s.side;\n                yield side * side;\n            }\n        };\n    }\n\n    public static void main(String[] args) throws Exception {\n        String report = """\n            Orders: %d\n            Limit:  \\t%d "quoted"\n            """.formatted(args.length, LIMIT);\n        char sep = \'\\n\', quote = \'\\\'\';\n        float ratio = 1.5e-3f;\n        synchronized (OrderService.class) {\n            System.out.println(report + sep + quote + ratio + (MASK >>> 2));\n        }\n        assert args != null : "args";\n    }\n}\n',
  'javascript':
      'import { EventEmitter } from \'node:events\';\n\nexport class Queue extends EventEmitter {\n  #items = [];\n  constructor({ concurrency = 4, retries = 2 } = {}) {\n    super();\n    this.concurrency = concurrency;\n    this.retries = retries;\n  }\n\n  push(task) {\n    this.#items.push({ task, attempts: 0 });\n    this.emit(\'queued\', this.#items.length);\n    return this;\n  }\n\n  async run() {\n    const workers = Array.from({ length: this.concurrency }, async () => {\n      while (this.#items.length > 0) {\n        const job = this.#items.shift();\n        try {\n          const result = await job.task();\n          this.emit(\'done\', result);\n        } catch (err) {\n          if (++job.attempts <= this.retries) this.#items.push(job);\n          else console.error(`failed after \${job.attempts} tries`, /timeout/i.test(err.message));\n        }\n      }\n    });\n    await Promise.all(workers);\n  }\n}\n',
