      'import React, { useState, useEffect } from \'react\';\nimport { Card } from \'./components/card\';\n\n// A searchable list of users.\nexport default function UserList({ users, onSelect, title = \'Users\' }) {\n  const [query, setQuery] = useState(\'\');\n  const [open, setOpen] = useState(false);\n\n  useEffect(() => {\n    if (query.length > 2 && users.length < 100) {\n      console.log(`searching \${query}`);\n    }\n  }, [query, users]);\n\n  const visible = users.filter((u) => u.name.includes(query));\n\n  return (\n    <Card className="user-list" data-count={visible.length}>\n      <h2>{title} &amp; friends</h2>\n      <input\n        type="search"\n        value={query}\n        onChange={(e) => setQuery(e.target.value)}\n        disabled={!users.length}\n      />\n      {/* Nothing to show yet */}\n      {visible.length === 0 ? (\n        <p className="empty">Don\'t panic, no matches.</p>\n      ) : (\n        <ul>\n          {visible.map((user) => (\n            <li key={user.id} onClick={() => onSelect(user)}>\n              <strong>{user.name}</strong> is {user.age > 18 ? \'adult\' : \'minor\'}\n            </li>\n          ))}\n        </ul>\n      )}\n      {open && <Modal.Dialog {...user} onClose={() => setOpen(false)} />}\n      <>\n        <span>a</span>\n        <span>b</span>\n      </>\n    </Card>\n  );\n}\n\nconst Badge = ({ count }) => <span className="badge">{count > 99 ? \'99+\' : count}</span>;\nconst same = 1 < 2 && 3 > 2;\n',
