      '#!/usr/bin/env julia\n#= Simple statistics module.\n   #= nested comment =#\n=#\nmodule Stats\n\nusing LinearAlgebra, Statistics\nimport Base: show\n\nexport Summary, summarize, @timed_log\n\n"""\n    Summary{T<:Real}\n\nHolds summary statistics for a sample of `T`.\n"""\nstruct Summary{T<:Real}\n    n::Int\n    mean::Float64\n    std::T\nend\n\nmutable struct Counter\n    value::Int\nend\n\nfunction summarize(xs::AbstractVector{T}) where {T<:Real}\n    isempty(xs) && throw(ArgumentError("empty sample"))\n    μ = mean(xs)\n    σ = length(xs) > 1 ? std(xs) : zero(T)\n    return Summary{T}(length(xs), μ, σ)\nend\n\nincrement!(c::Counter, by=1) = (c.value += by; c)\n\nshow(io::IO, s::Summary) = print(io, "Summary(n=\$(s.n), mean=\$(round(s.mean; digits=2)))")\n\nmacro timed_log(expr)\n    quote\n        local t0 = time()\n        local result = \$(esc(expr))\n        println("took \$(time() - t0) s")\n        result\n    end\nend\n\nend # module\n\nxs = [1.5, 2.0, 3.25, 1e-3, 0x1F]\ns = Stats.summarize(xs)\nA = [1 2; 3 4]\'\nc = \'x\'\nnewline = \'\\n\'\npattern = r"^\\d+\$"\nraw_path = raw"C:\\temp\\file"\nname = "world"\nprintln("Hello, \$name! First: \$(xs[1]), sym: ", :done, " range: ", 1:3)\nfor (i, x) in enumerate(xs)\n    i > 3 && break\n    @show i x\nend\nz = 3 + 4im\nresult = xs isa Vector{Float64} ? nothing : missing\n',
