      'package com.example.cart\n\nimport kotlinx.coroutines.flow.*\nimport java.time.Instant\n\n/**\n * A shopping cart. Totals are in cents.\n * @property owner who the cart belongs to\n * /* nested comment in docs */\n */\n@JvmInline\nvalue class Cents(val amount: Long)\n\nsealed interface Event {\n    data class Added(val sku: String, val qty: Int = 1) : Event\n    data object Cleared : Event\n}\n\nclass Cart(private val owner: String) {\n    private val items = mutableMapOf<String, Int>()\n    var updatedAt: Instant? = null\n        private set\n\n    companion object {\n        const val MAX_ITEMS = 1_000\n        private const val MASK = 0xFF_FFL\n    }\n\n    suspend fun apply(event: Event): Boolean = when (event) {\n        is Event.Added -> {\n            require(event.qty > 0) { "qty must be positive, got \${event.qty}" }\n            items.merge(event.sku, event.qty, Int::plus)\n            updatedAt = Instant.now()\n            true\n        }\n        Event.Cleared -> items.clear().let { false }\n    }\n\n    fun summary(): String {\n        val lines = items.entries.joinToString("\\n") { (sku, qty) -> "\$sku x\$qty" }\n        return """\n            |Cart for \$owner (\${items.size} items)\n            |\$lines \\n stays raw\n        """.trimMargin()\n    }\n\n    inline fun <reified T> find(predicate: (T) -> Boolean): T? = null\n\n    fun loop() {\n        outer@ for (i in 0 until 10) {\n            if (i % 2 == 0) continue@outer\n            val c = \'x\'; val tab = \'\\t\'; val pi = 3.14f\n            println(`is`(i) && c != tab && pi > 1e-3)\n        }\n    }\n\n    private fun `is`(n: Int) = n in 1..9 && n !in setOf(4, 5)\n}\n\nfun main() = runBlocking {\n    val cart = Cart("ada")\n    listOf(Event.Added("apple", 2), Event.Cleared).asFlow().collect { cart.apply(it) }\n    println(cart.summary() ?: "empty")\n}\n',
