      '#!/usr/bin/env lua\n-- Inventory module.\n--[[\n  Multi-line comment with [brackets] and "quotes".\n]]\n--[==[ a level-2 comment that contains ]] safely ]==]\n\nlocal json = require("dkjson")\nlocal M = {}\nM.__index = M\n\nlocal MAX <const> = 64\nlocal escape = "tab\\tnewline\\n\\"quoted\\" \\u{48}"\nlocal literal = [[\nraw text with \\n no escapes and \'quotes\'\n]]\nlocal nested = [=[ contains ]] and [[ ]=]\n\nfunction M.new(name, capacity)\n  local self = setmetatable({}, M)\n  self.name = name or "default"\n  self.capacity = capacity or MAX\n  self.items = {}\n  return self\nend\n\nfunction M:add(item, count)\n  count = count or 1\n  if #self.items + count > self.capacity then\n    error(("inventory %s is full"):format(self.name), 2)\n  elseif count <= 0 then\n    return false\n  end\n  for i = 1, count do\n    self.items[#self.items + 1] = item\n  end\n  return true\nend\n\nfunction M:report()\n  local totals = {}\n  for _, item in ipairs(self.items) do\n    totals[item] = (totals[item] or 0) + 1\n  end\n  for name, n in pairs(totals) do\n    print(string.format("%-10s %3d", name, n))\n  end\n  return json.encode { name = self.name, size = #self.items }\nend\n\nlocal inv = M.new("pack", 0x10)\ninv:add("potion", 3)\nprint(inv:report(), 1e3, 0.5, 3 // 2, 7 ~= 8, "a" .. "b")\ngoto done\n::done::\nreturn M\n',
