      '# Build settings\nCC      ?= cc\nCFLAGS  := -O2 -Wall -Wextra\nLDLIBS  += -lm\nSRC     := \$(wildcard src/*.c)\nOBJ     := \$(patsubst src/%.c,build/%.o,\$(SRC))\nVERSION := \$(shell git describe --tags 2>/dev/null || echo dev)\n\nexport PREFIX ?= /usr/local\n\n.PHONY: all clean install test\n\nall: build/app\n\nbuild/app: \$(OBJ) | build\n	@echo "linking \$@ from \$^"\n	\$(CC) \$(CFLAGS) -o \$@ \$^ \$(LDLIBS)\n\nbuild/%.o: src/%.c include/%.h\n	\$(CC) \$(CFLAGS) -Iinclude -c \$< -o \$@\n\nbuild:\n	mkdir -p \$@\n\nifeq (\$(OS),Windows_NT)\n    EXE := .exe\nelse\n    EXE :=\nendif\n\ndefine banner\n	@echo "== \$(1) =="\nendef\n\ninstall: build/app\n	\$(call banner,installing)\n	install -m 755 build/app \$(DESTDIR)\$(PREFIX)/bin/app\$(EXE)\n\ntest: all\n	./build/app --self-test && \\\n	  echo "ok: \$\${HOME}"\n\nclean:\n	-rm -rf build # remove everything\n',
