      '; Prints a message and exits (Linux x86-64).\n%define SYS_WRITE 1\n%define SYS_EXIT  60\n\nbits 64\ndefault rel\n\nsection .data\n    msg     db  "Hello, world!", 10, 0\n    len     equ \$ - msg\n    table   dw  0x10, 20h, 0b1010, 1010b, 777q, 12\n    pi      dq  3.14159\n    quote   db  \'single\', `tick\\n`\n\nsection .bss\n    buffer  resb 64\n\nsection .text\n    global _start\n\n_start:\n    mov     rax, SYS_WRITE\n    mov     rdi, 1\n    lea     rsi, [msg]\n    mov     rdx, len\n    syscall\n\n    xor     ecx, ecx            ; counter = 0\n.loop:\n    cmp     rcx, 10\n    jge     .done\n    inc     rcx\n    movzx   eax, byte [rsi + rcx]\n    test    al, al\n    jz      .done\n    cmovne  r8, rcx\n    jmp     .loop\n\n.done:\n    push    r12\n    call    helper\n    pop     r12\n    vxorps  ymm0, ymm0, ymm0\n    MOV     RAX, SYS_EXIT       ; upper case works too\n    xor     edi, edi\n    syscall\n\nhelper:\n    mov     qword [buffer], r12\n    ret\n',
