      '#import <Foundation/Foundation.h>\n#import "ProfileStore.h"\n#define kTimeout 30.0\n\nNS_ASSUME_NONNULL_BEGIN\n\n/** Stores user profiles. */\n@interface ProfileStore : NSObject <NSCopying>\n@property (nonatomic, copy, readonly) NSArray<NSString *> *names;\n@property (nonatomic, weak, nullable) id<ProfileDelegate> delegate;\n- (instancetype)initWithCapacity:(NSUInteger)capacity NS_DESIGNATED_INITIALIZER;\n+ (instancetype)sharedStore;\n@end\n\n@implementation ProfileStore {\n    NSMutableArray<NSString *> *_names;\n    BOOL _loaded;\n}\n\n+ (instancetype)sharedStore {\n    static ProfileStore *shared = nil;\n    static dispatch_once_t once;\n    dispatch_once(&once, ^{\n        shared = [[self alloc] initWithCapacity:16];\n    });\n    return shared;\n}\n\n- (instancetype)initWithCapacity:(NSUInteger)capacity {\n    if ((self = [super init])) {\n        _names = [NSMutableArray arrayWithCapacity:capacity];\n        _loaded = NO;\n    }\n    return self;\n}\n\n- (void)addName:(NSString *)name {\n    if (name.length == 0) return; // ignore empty names\n    [_names addObject:name];\n    NSLog(@"Added %@ (%lu total)\\n", name, (unsigned long)_names.count);\n    NSDictionary *info = @{@"name": name, @"count": @(_names.count), @"ok": @YES};\n    NSArray *pair = @[@1, @2.5];\n    [self.delegate store:self didUpdate:info with:pair];\n}\n\n- (id)copyWithZone:(nullable NSZone *)zone {\n    ProfileStore *copy = [[ProfileStore allocWithZone:zone] initWithCapacity:0x10];\n    @synchronized (self) {\n        copy->_names = [_names mutableCopy];\n    }\n    return copy;\n}\n\n@end\n\nNS_ASSUME_NONNULL_END\n',
