      '(** A binary search tree. *)\nmodule Tree = struct\n  type \'a t =\n    | Leaf\n    | Node of \'a t * \'a * \'a t\n  [@@deriving show]\n\n  let empty = Leaf\n\n  (* Insert keeps the tree ordered. (* nested *) *)\n  let rec insert cmp x = function\n    | Leaf -> Node (Leaf, x, Leaf)\n    | Node (l, v, r) as node ->\n      let c = cmp x v in\n      if c < 0 then Node (insert cmp x l, v, r)\n      else if c > 0 then Node (l, v, insert cmp x r)\n      else node\n\n  let rec to_list = function\n    | Leaf -> []\n    | Node (l, v, r) -> to_list l @ (v :: to_list r)\nend\n\nexception Invalid_input of string\n\nlet parse_int (s : string) : int option =\n  match int_of_string_opt (String.trim s) with\n  | Some n when n >= 0 -> Some n\n  | Some _ -> raise (Invalid_input s)\n  | None -> None\n\nlet banner = {|raw "text" with \\n no escapes|}\nlet tagged = {sql|SELECT * FROM t|sql}\n\nlet () =\n  let t = List.fold_left (fun acc x -> Tree.insert compare x acc) Tree.empty [5; 3; 8; 1] in\n  let chars = [\'a\'; \'\\n\'; \'\\\'\'; \'\\065\'] in\n  let mask = 0xFF land 0b1010 lor 0o17 in\n  let big = 1_000_000L and pi = 3.14159 in\n  Printf.printf "%d items, mask=%d, big=%Ld, pi=%.2f\\n"\n    (List.length (Tree.to_list t)) mask big pi;\n  ignore chars;\n  print_endline banner;\n  print_endline tagged;\n  assert (not false)\n',
  'perl':
      '#!/usr/bin/perl\nuse strict;\nuse warnings;\n\n# Summarise an access log.\nmy %hits;\nmy @errors = ();\nmy \$total = 0;\nmy \$pattern = qr/^(\\S+) \\S+ \\S+ \\[([^\\]]+)\\] "(\\w+) ([^"]+)"/;\n\nwhile (my \$line = <STDIN>) {\n    chomp \$line;\n    next unless \$line =~ m{\$pattern};\n    my (\$ip, \$when, \$method, \$path) = (\$1, \$2, \$3, \$4);\n    \$hits{\$ip}++;\n    \$total += 1;\n    push @errors, \$path if \$line =~ /\\s5\\d\\d\\s/;\n    (my \$clean = \$path) =~ s/\\?.*\$//;\n    \$clean =~ tr/A-Z/a-z/;\n}\n\nmy @top = (sort { \$hits{\$b} <=> \$hits{\$a} } keys %hits)[0 .. 2];\nmy @words = qw(alpha beta gamma);\nmy \$single = q(no \$interpolation here);\nmy \$double = qq{total: \$total, first: \$top[0], count: \${\\ scalar @top}};\n\nprintf "%-15s %d\\n", \$_, \$hits{\$_} for @top;\nprint "last index: \$#top, words: @words\\n";\n\nmy %config = (\n    name    => \'report\',\n    limit   => 10,\n    verbose => 0,\n);\n\nsub report {\n    my (\$self, %args) = @_;\n    my \$out = \$args{fh} // \\*STDOUT;\n    print {\$out} <<"END";\nReport for \$config{name}\nErrors: \${\\ scalar @errors}\nEND\n    print {\$out} <<\'RAW\';\nLiteral \$text, no interpolation.\nRAW\n    return wantarray ? @errors : scalar @errors;\n}\n\nmy \$obj = Report::Writer->new(limit => \$config{limit});\n\$obj->write(report(undef, fh => \\*STDERR));\ndie "no data\\n" unless \$total > 0x0;\n\n__END__\n\n=head1 NAME\n\nreport.pl - summarise logs\n',
