      '<?php\n\ndeclare(strict_types=1);\n\nnamespace App\\Http\\Controllers;\n\nuse App\\Models\\User;\nuse Illuminate\\Http\\Request;\n\n/**\n * Handles user profile pages.\n */\n#[Route(\'/users\', methods: [\'GET\'])]\nfinal class UserController extends Controller\n{\n    private const PAGE_SIZE = 25;\n\n    public function __construct(private readonly UserRepository \$users) {}\n\n    public function show(Request \$request, int \$id): array|null\n    {\n        \$user = \$this->users->find(\$id) ?? throw new NotFoundException("User {\$id} not found");\n        \$name = \$user?->profile[\'display\'] ?? \'anonymous\';\n        // Null-safe access and the null-coalescing operator.\n        \$greeting = "Hello, \$name! You have {\$user->unread} messages.";\n        \$query = <<<SQL\n            SELECT * FROM users\n            WHERE id = {\$id} AND name = \'\$name\'\n            SQL;\n        \$raw = <<<\'TEXT\'\n            No \$interpolation here.\n            TEXT;\n\n        return match (true) {\n            \$id < 0 => null,\n            default => [\'greeting\' => \$greeting, \'size\' => self::PAGE_SIZE, \'hex\' => 0x1F],\n        };\n    }\n\n    public static function slug(string \$title): string\n    {\n        return strtolower(preg_replace(\'/[^a-z0-9]+/i\', \'-\', trim(\$title)));\n    }\n}\n\n\$items = array_map(fn(\$x) => \$x * 2, [1, 2, 3]);\necho count(\$items), PHP_EOL;\n?>\n<ul class="items">\n  <?php foreach (\$items as \$item): ?>\n    <li data-value="<?= \$item ?>">Item <?= htmlspecialchars((string) \$item) ?></li>\n  <?php endforeach; ?>\n</ul>\n<script>const total = 3;</script>\n',
  'powershell':
      '#Requires -Version 7.0\n<#\n.SYNOPSIS\n    Cleans up old build artifacts.\n#>\n[CmdletBinding(SupportsShouldProcess)]\nparam(\n    [Parameter(Mandatory = \$true)]\n    [string]\$Path,\n\n    [int]\$Days = 30,\n    [switch]\$WhatIfOnly\n)\n\nSet-StrictMode -Version Latest\n\$ErrorActionPreference = \'Stop\'\n\nfunction Get-OldItem {\n    param([string]\$Root, [datetime]\$Before)\n    Get-ChildItem -Path \$Root -Recurse -File |\n        Where-Object { \$_.LastWriteTime -lt \$Before -and \$_.Length -gt 1KB }\n}\n\n\$cutoff = (Get-Date).AddDays(-\$Days)\n\$items = @(Get-OldItem -Root \$Path -Before \$cutoff)\n\$total = (\$items | Measure-Object -Property Length -Sum).Sum\n\nWrite-Host "Found \$(\$items.Count) files (\$([math]::Round(\$total / 1MB, 2)) MB) under \$Path"\nWrite-Host \'Single quotes: no \$expansion, it\'\'s literal\'\nWrite-Host "Escapes: tab`there, newline`n, dollar `\$Path"\n\n\$summary = @"\nPath:   \$Path\nBefore: \$(\$cutoff.ToString(\'yyyy-MM-dd\'))\n"@\n\n\$literal = @\'\nNothing \$expanded here.\n\'@\n\nforeach (\$item in \$items) {\n    if (\$WhatIfOnly) {\n        Write-Verbose "Would remove \$(\$item.FullName)"\n        continue\n    }\n    try {\n        Remove-Item -LiteralPath \$item.FullName -Force -ErrorAction Stop\n    }\n    catch [System.UnauthorizedAccessException] {\n        Write-Warning "Access denied: \$(\$_.Exception.Message)"\n    }\n}\n\n\$hash = @{ Name = \'build\'; Count = \$items.Count; Enabled = \$true; Home = \$env:HOME }\nif (\$hash.Count -ge 0x10 -or \$null -eq \$summary) { exit 1 }\n[System.IO.Path]::Combine(\$Path, \'log.txt\') | Out-File -FilePath "\$Path\\clean.log"\n',
