  'python':
      'from __future__ import annotations\n\nimport json\nfrom dataclasses import dataclass, field\nfrom pathlib import Path\n\n\n@dataclass\nclass Config:\n    name: str\n    retries: int = 3\n    tags: list[str] = field(default_factory=list)\n\n    @classmethod\n    def load(cls, path: Path) -> "Config":\n        """Read a config file, falling back to defaults."""\n        try:\n            data = json.loads(path.read_text(encoding="utf-8"))\n        except FileNotFoundError:\n            return cls(name=path.stem)\n        return cls(**{k: v for k, v in data.items() if k in cls.__annotations__})\n\n    def summary(self) -> str:\n        return f"{self.name}: {self.retries} retries, tags={\', \'.join(self.tags) or None!r}"\n\n\nif __name__ == "__main__":\n    for p in Path(".").glob("*.json"):\n        print(Config.load(p).summary())  # one per file\n',
  'r':
      '#!/usr/bin/env Rscript\n# Summarise a sales dataset.\nlibrary(dplyr)\nlibrary(ggplot2)\n\n#\' Load sales data from a CSV file.\n#\' @param path File to read.\nload_sales <- function(path, sep = ",") {\n  stopifnot(file.exists(path))\n  data <- read.csv(path, sep = sep, stringsAsFactors = FALSE)\n  data\$date <- as.Date(data\$date, format = "%Y-%m-%d")\n  data[!is.na(data\$amount), ]\n}\n\nsales <- load_sales("sales.csv")\nregions <- c("north", \'south\', "east", "west")\nthreshold <- 1e3\nbig <- 0x1F + 10L + 2i\n\nsummary_tbl <- sales %>%\n  filter(region %in% regions, amount > threshold) %>%\n  group_by(region) %>%\n  summarise(total = sum(amount), n = n(), .groups = "drop") |>\n  arrange(desc(total))\n\n`odd name` <- TRUE\npattern <- r"(\\d+\\.\\d+)"\npath <- r"[C:\\data\\file.txt]"\n\nfor (i in seq_len(nrow(summary_tbl))) {\n  row <- summary_tbl[i, ]\n  if (is.null(row) || row\$n == 0) {\n    next\n  } else if (row\$total > 5000) {\n    message(sprintf("%s: %.1f (large)", row\$region, row\$total))\n  } else {\n    cat(paste0(row\$region, ": ", row\$total, "\\n"))\n  }\n}\n\nresult <- tryCatch(\n  stop("boom"),\n  error = function(e) NA_real_,\n  finally = cat("done\\n")\n)\n\nplot <- ggplot(summary_tbl, aes(x = region, y = total)) +\n  geom_col(fill = "steelblue") +\n  labs(title = "Sales by region")\n\nsquares <- sapply(1:10, \\(x) x^2)\nprint(list(result = result, missing = NA, nothing = NULL, inf = -Inf))\n',
  'ruby':
      '#!/usr/bin/env ruby\n# frozen_string_literal: true\n\nrequire \'json\'\nrequire_relative \'lib/client\'\n\n=begin\nBlock comment: nothing here is code.\ndef ignored; end\n=end\n\nmodule Billing\n  class Invoice < Base::Record\n    attr_reader :id, :items\n    TAX_RATE = 0.2r\n    @@count = 0\n\n    def initialize(id, items: [], currency: :usd)\n      @id = id\n      @items = items\n      @currency = currency\n      @@count += 1\n    end\n\n    def total?\n      items.any? && total > 0\n    end\n\n    def total\n      items.sum { |item| item[:price] * (1 + TAX_RATE) }\n    end\n\n    def self.parse(text)\n      data = JSON.parse(text, symbolize_names: true)\n      new(data[:id], items: data.fetch(:items, []))\n    rescue JSON::ParserError => e\n      warn "bad invoice: #{e.message} (#{text.length} bytes)"\n      nil\n    end\n\n    def to_s = "Invoice ##{id}: #{format(\'%.2f\', total)} #{@currency.upcase}"\n  end\nend\n\nwords = %w[alpha beta gamma]\ntags = %i(draft sent paid)\npath = %q{C:\\no\\interpolation #{here}}\npattern = /\\A(\\d{3})-(\\d{4})\\z/i\nmatched = "555-1234" =~ pattern\nratio = 10 / 3 * 1_000 + 0xFF + 0b1010\nputs \$PROGRAM_NAME, \$stdout.sync, ENV.fetch(\'HOME\', \'~\')\n\nsql = <<~SQL.strip\n  SELECT * FROM invoices\n  WHERE id = #{Integer(ARGV.first || 1)} -- it\'s interpolated\nSQL\n\nraw = <<~\'TEXT\'\n  Nothing #{interpolated} here.\nTEXT\n\n[1, 2, 3].each_with_index do |value, index|\n  next if value.odd?\n  printf("%d:%d\\n", index, value) unless defined?(SKIP)\nend\n\n__END__\ndata section: "unclosed and ignored\n',
  'rust':
      '//! A tiny key-value store.\n#![allow(dead_code)]\n\nuse std::collections::HashMap;\nuse std::fmt::{self, Display};\n\n/// A stored value with a lifetime-bound view.\n#[derive(Debug, Clone, PartialEq)]\npub enum Value {\n    Int(i64),\n    Text(String),\n    Bytes(Vec<u8>),\n}\n\npub struct Store<\'a> {\n    items: HashMap<&\'a str, Value>,\n    limit: usize,\n}\n\nimpl<\'a> Store<\'a> {\n    pub fn new(limit: usize) -> Self {\n        Self { items: HashMap::with_capacity(16), limit }\n    }\n\n    pub fn put(&mut self, key: &\'a str, value: Value) -> Result<(), String> {\n        if self.items.len() >= self.limit {\n            return Err(format!("store full ({} items)", self.limit));\n        }\n        self.items.insert(key, value);\n        Ok(())\n    }\n\n    fn first_char(&self, key: &str) -> Option<char> {\n        match self.items.get(key)? {\n            Value::Text(s) => s.chars().next(),\n            _ => None,\n        }\n    }\n}\n\nimpl Display for Value {\n    fn fmt(&self, f: &mut fmt::Formatter<\'_>) -> fmt::Result {\n        match self {\n            Value::Int(n) => write!(f, "{n}"),\n            Value::Text(s) => write!(f, "{s:?}"),\n            Value::Bytes(b) => write!(f, "{} bytes", b.len()),\n        }\n    }\n}\n\n/* Outer /* nested */ comment. */\nfn main() {\n    let raw = r#"C:\\path "quoted""#;\n    let bytes = b"\\x00\\xff";\n    let (a, b, c) = (\'x\', \'\\n\', b\'\\\'\');\n    let big = 1_000_000u64 + 0xFF_u64 + 0b1010 + 0o17;\n    let pi = 3.141_59_f64;\n    let mut store = Store::new(10);\n    store.put("answer", Value::Int(42)).unwrap();\n    let v: Vec<_> = (0..big).filter(|n| n % 2 == 0).take(3).collect::<Vec<u64>>();\n    println!("{raw} {bytes:?} {a}{b}{c} {pi} {v:?}");\n    \'outer: loop { break \'outer; }\n}\n',
  'scala':
      'package shop\n\nimport scala.concurrent.{ExecutionContext, Future}\nimport scala.util.{Failure, Success}\n\n/** An order line.\n  * /* nested comment in docs */\n  */\nfinal case class Line(sku: String, qty: Int, price: BigDecimal):\n  def total: BigDecimal = price * qty\n\nenum Status:\n  case Open, Paid, Shipped\n\ntrait Repository[F[_]]:\n  def find(id: Long): F[Option[Line]]\n\ngiven ExecutionContext = ExecutionContext.global\n\nobject Orders extends App:\n  private val limit = 1_000L\n  private val mask = 0xFF\n  val lines = List(Line("apple", 2, BigDecimal("0.5")), Line("pear", 1, 1.25))\n\n  extension (line: Line)\n    def describe: String = s"\${line.sku} x\${line.qty} = \${line.total}"\n\n  @annotation.tailrec\n  def sum(xs: List[Line], acc: BigDecimal = 0): BigDecimal = xs match\n    case Nil          => acc\n    case head :: tail => sum(tail, acc + head.total)\n\n  def status(paid: Boolean): Status =\n    if paid then Status.Paid else Status.Open\n\n  val report =\n    s"""Orders: \${lines.size}\n       |Total: \${sum(lines)} \$\$ literal dollar\n       |""".stripMargin\n\n  val formatted = f"ratio \${2.5e-3}%.4f and \${limit}%d"\n  val path = raw"C:\\temp\\n stays"\n  val c = \'x\'\n\n  for\n    line <- lines\n    if line.qty > 0\n  do println(line.describe)\n\n  Future(sum(lines)).onComplete {\n    case Success(total) => println(s"total \$total")\n    case Failure(error) => Console.err.println(error.getMessage)\n  }\nend Orders\n',
