      '@use \'sass:math\';\n@import "base/reset";\n\n// Design tokens\n\$brand: #b0226e !default;\n\$gap: 12px;\n\$breakpoints: (small: 576px, large: 992px);\n\n@mixin respond(\$size) {\n  @media (min-width: map-get(\$breakpoints, \$size)) {\n    @content;\n  }\n}\n\n%card-base {\n  border-radius: math.div(\$gap, 2);\n}\n\n/* Components */\n.card {\n  @extend %card-base;\n  padding: \$gap * 2;\n  color: darken(\$brand, 10%);\n\n  &:hover { transform: translateY(-2px); }\n  &__title {\n    font: #{\$gap + 4}/1.2 system-ui, sans-serif;\n    margin-#{\$side}: 0;\n  }\n\n  @include respond(large) {\n    padding: \$gap * 3;\n  }\n\n  @each \$name, \$value in \$breakpoints {\n    .col-#{\$name} { width: \$value; }\n  }\n}\n\n@function rem(\$px) {\n  @if \$px == 0 { @return 0; }\n  @return math.div(\$px, 16px) * 1rem;\n}\n',
  'solidity':
      '// SPDX-License-Identifier: MIT\npragma solidity ^0.8.24;\n\nimport {IERC20} from "./interfaces/IERC20.sol";\n\n/// @title A simple vault.\n/// @notice Holds deposits until an unlock time.\ncontract Vault is Ownable {\n    error TooEarly(uint256 unlockAt);\n    event Deposited(address indexed from, uint256 amount);\n\n    struct Deposit {\n        uint128 amount;\n        uint64 unlockAt;\n        bool withdrawn;\n    }\n\n    mapping(address => Deposit[]) private deposits;\n    uint256 public constant MIN_DEPOSIT = 0.01 ether;\n    uint256 public immutable lockTime;\n    bytes32 private constant TAG = hex"deadbeef";\n    string private greeting = unicode"Hello 👋";\n\n    /**\n     * @dev Sets the lock time.\n     * @param lockDays Number of days deposits stay locked.\n     */\n    constructor(uint256 lockDays) {\n        lockTime = lockDays * 1 days;\n    }\n\n    modifier minimum(uint256 amount) {\n        require(amount >= MIN_DEPOSIT, "deposit too small");\n        _;\n    }\n\n    function deposit() external payable minimum(msg.value) {\n        deposits[msg.sender].push(\n            Deposit({amount: uint128(msg.value), unlockAt: uint64(block.timestamp + lockTime), withdrawn: false})\n        );\n        emit Deposited(msg.sender, msg.value);\n    }\n\n    function withdraw(uint256 index) external {\n        Deposit storage d = deposits[msg.sender][index];\n        if (block.timestamp < d.unlockAt) revert TooEarly(d.unlockAt);\n        d.withdrawn = true;\n        (bool ok, ) = payable(msg.sender).call{value: d.amount}("");\n        assert(ok);\n    }\n\n    function hash(string calldata text) public pure returns (bytes32) {\n        unchecked {\n            return keccak256(abi.encodePacked(text, uint8(0x1f), \'single\'));\n        }\n    }\n}\n',
  'sql':
      '-- Monthly revenue per region\nWITH monthly AS (\n  SELECT r.name AS region,\n         date_trunc(\'month\', o.created_at) AS month,\n         SUM(o.total) AS revenue,\n         COUNT(DISTINCT o.customer_id) AS customers\n  FROM orders o\n  JOIN regions r ON r.id = o.region_id\n  WHERE o.status = \'paid\' AND o.created_at >= \'2026-01-01\'\n  GROUP BY 1, 2\n)\nSELECT region, month, revenue,\n       revenue / NULLIF(customers, 0) AS per_customer,\n       LAG(revenue) OVER (PARTITION BY region ORDER BY month) AS previous\nFROM monthly\nORDER BY region, month DESC\nLIMIT 100;\n',
