      'import SwiftUI\nimport Foundation\n\n/// A user profile loaded from the network.\n/* An outer comment /* with a nested one */ still a comment */\nstruct Profile: Codable, Identifiable, Sendable {\n    let id: UUID\n    var name: String\n    var age: Int?\n}\n\n@MainActor\nfinal class ProfileStore: ObservableObject {\n    @Published private(set) var profiles: [Profile] = []\n    private let session: URLSession\n\n    init(session: URLSession = .shared) {\n        self.session = session\n    }\n\n    func load(from url: URL) async throws -> [Profile] {\n        let (data, response) = try await session.data(from: url)\n        guard let http = response as? HTTPURLResponse, http.statusCode == 200 else {\n            throw URLError(.badServerResponse)\n        }\n        let decoded = try JSONDecoder().decode([Profile].self, from: data)\n        profiles = decoded.sorted { \$0.name < \$1.name }\n        return decoded\n    }\n}\n\nenum Level: Int, CaseIterable {\n    case low = 0x01, high = 0b10\n    var label: String { "Level \\(rawValue) of \\(Self.allCases.count)" }\n}\n\nstruct ProfileRow: View {\n    let profile: Profile\n\n    var body: some View {\n        HStack {\n            Text(profile.name).font(.headline)\n            Spacer()\n            if let age = profile.age {\n                Text("age \\(age + (age > 99 ? 0 : 1))\\t✓")\n            }\n        }\n        .padding(8.5)\n    }\n}\n\nlet raw = #"C:\\path\\n stays "raw" here"#\nlet multi = """\n    Line one\n    Interpolated: \\(Level.high.label)\n    """\nlet `default` = 1_000\n\n#if DEBUG\nlet selector = #selector(ProfileStore.reload)\n#endif\n\n#Preview {\n    ProfileRow(profile: Profile(id: UUID(), name: "Ada", age: nil))\n}\n',
