  'tsx':
      'import type { ReactNode } from \'react\';\nimport { useMemo, useState } from \'react\';\n\ninterface ListProps<T> {\n  items: readonly T[];\n  render: (item: T, index: number) => ReactNode;\n  empty?: ReactNode;\n}\n\ntype Status = \'idle\' | \'loading\' | \'done\';\n\nexport function List<T,>({ items, render, empty = null }: ListProps<T>): JSX.Element {\n  const [status, setStatus] = useState<Status>(\'idle\');\n  const sorted = useMemo(() => [...items].sort(), [items]);\n\n  if (items.length < 1) return <>{empty}</>;\n\n  return (\n    <ul role="list" aria-busy={status === \'loading\'}>\n      {sorted.map((item, i) => (\n        <li key={i} className={i % 2 === 0 ? \'even\' : \'odd\'}>\n          {render(item, i)}\n        </li>\n      ))}\n    </ul>\n  );\n}\n\nconst identity = <T,>(value: T): T => value;\n\nexport const Page: React.FC<{ title: string }> = ({ title }) => {\n  const count: number = 3;\n  const big = count > 2 && count < 10;\n  return (\n    <main>\n      <h1 title={`Page: \${title}`}>{title}</h1>\n      {big ? <Alert.Banner level="info" /> : null}\n      <List<number> items={[1, 2, 3]} render={(n) => <b>{n}</b>} />\n      <svg:circle cx="5" cy="5" r="4" />\n    </main>\n  );\n};\n\nenum Level { Low = 1, High = 2 }\n',
  'typescript':
      'import type { Request, Response } from \'express\';\n\nexport enum Status { Active = \'active\', Disabled = \'disabled\' }\n\ninterface User<T extends object = {}> {\n  readonly id: number;\n  name: string;\n  email?: string;\n  meta: T;\n}\n\ntype Handler = (req: Request, res: Response) => Promise<void>;\n\nexport abstract class Repository<T extends User> {\n  private cache = new Map<number, T>();\n  protected constructor(private readonly table: string) {}\n\n  abstract load(id: number): Promise<T | undefined>;\n\n  async find(id: number): Promise<T | undefined> {\n    const hit = this.cache.get(id);\n    if (hit !== undefined) return hit;\n    const user = await this.load(id);\n    user && this.cache.set(id, user);\n    return user as T;\n  }\n}\n\nexport const handler: Handler = async (req, res) => {\n  const limit = Number(req.query.limit ?? 10) satisfies number;\n  res.json({ ok: true, limit, at: `\${Date.now()}` });\n};\n',
