  'zig':
      '//! Parses key=value lines.\nconst std = @import("std");\nconst Allocator = std.mem.Allocator;\n\n/// A parsed entry.\npub const Entry = struct {\n    key: []const u8,\n    value: []const u8,\n    line: u32 = 0,\n};\n\npub const ParseError = error{ MissingEquals, EmptyKey } || Allocator.Error;\n\npub fn parse(allocator: Allocator, text: []const u8) ParseError![]Entry {\n    var list = std.ArrayList(Entry).init(allocator);\n    errdefer list.deinit();\n    var it = std.mem.splitScalar(u8, text, \'\\n\');\n    var line: u32 = 1;\n    while (it.next()) |raw| : (line += 1) {\n        const trimmed = std.mem.trim(u8, raw, " \\t");\n        if (trimmed.len == 0 or trimmed[0] == \'#\') continue;\n        const eq = std.mem.indexOfScalar(u8, trimmed, \'=\') orelse return error.MissingEquals;\n        if (eq == 0) return error.EmptyKey;\n        try list.append(.{ .key = trimmed[0..eq], .value = trimmed[eq + 1 ..], .line = line });\n    }\n    return list.toOwnedSlice();\n}\n\nconst help =\n    \\\\usage: kv [file]\n    \\\\  prints every "key = value" pair\n;\n\ntest "parse two lines" {\n    const entries = try parse(std.testing.allocator, "a=1\\nb=0x2A\\n");\n    defer std.testing.allocator.free(entries);\n    try std.testing.expectEqual(@as(usize, 2), entries.len);\n    const mask: u7 = 0b101_0101;\n    const ratio: f64 = 1.5e3;\n    _ = mask;\n    _ = ratio;\n    var @"weird name": i32 = undefined;\n    @"weird name" = comptime blk: {\n        break :blk 7;\n    };\n    _ = help;\n}\n',
